# Simulated sites for the accuracy benchmark (fit.jl): NSITES independent sites per model of examples/data/cases.jl, with and without background, written with DynMoSim. Run from the LocMoFit.jl folder:
#     julia --project=../DynMoSim benchmarks/accuracy/generate.jl
# Writes data/<case>_<background|nobackground>.csv (localizations, SMAPpy column names, plus the site number) and the row-aligned data/<case>_<...>_truth.csv. The data are regenerated by this script and need not be committed.
include(joinpath(@__DIR__, "..", "..", "examples", "data", "cases.jl"))
const NSITES = 20
const OUT = joinpath(@__DIR__, "data")
mkpath(OUT)

for (i, (name, case)) in enumerate(pairs(CASES)), background in (true, false)
    sites = [
        smaptable.(simulate_site(Xoshiro(1000i + 2site + background), case; background)) for
        site in 1:NSITES
    ]
    function with_site(tables)
        return merge(
            (
                site=reduce(
                    vcat, [fill(k, length(first(t))) for (k, t) in enumerate(tables)]
                ),
            ),
            map((cols...) -> reduce(vcat, cols), tables...),
        )
    end
    tag = background ? "background" : "nobackground"
    writecsv(joinpath(OUT, "$(name)_$tag.csv"), with_site(first.(sites)))
    writecsv(joinpath(OUT, "$(name)_$(tag)_truth.csv"), with_site(last.(sites)))
    n = [length(first(s).x_nm) for s in sites]
    println("$name, $tag: $NSITES sites, $(minimum(n))–$(maximum(n)) localizations each")
end
